import com.google.javascript.jscomp.type.JSType;
import com.google.javascript.jscomp.type.JSTypeRegistry;
import com.google.javascript.phd.Node;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import com.google.javascript.rhino.jstype.EnumElementType;
import com.google.javascript.rhino.jstype.FunctionType;
import com.google.javascript.rhino.jstype.JSType;
import com.google.javascript.rhino.jstype.JSTypeNative;
import com.google.javascript.rhino.jstype.JSTypeRegistry;
import com.google.javascript.rhino.jstype.ObjectType;
import com.google.javascript.rhino.jstype.ParameterizedType;
import com.google.javascript.rhino.jstype.StaticSlot;
import com.google.javascript.rhino.jstype.TemplateType;
import com.google.javascript.rhino.jstype.UnionType;
import com.google.javascript.rhino.jstype.Visitor;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.Assert;
import static org.junit.Assert.*;
import static org.junit.Assert.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for declareNameInScope method in ChainableReverseAbstractInterpreter.
 */
public class ChainableReverseAbstractInterpreter_declareNameInScope_TriageGen0Test {

    private TestableChainableReverseAbstractInterpreter interpreter;

    @Mock private CodingConvention mockConvention;
    @Mock private JSTypeRegistry mockTypeRegistry;
    @Mock private FlowScope mockScope;
    @Mock private Node mockNode;
    @Mock private JSType mockType;
    @Mock private JSType mockOrigType;

    /**
     * A subclass to expose the protected method for testing.
     */
    private static class TestableChainableReverseAbstractInterpreter extends ChainableReverseAbstractInterpreter {
        protected TestableChainableReverseAbstractInterpreter(CodingConvention convention, JSTypeRegistry typeRegistry) {
            super(convention, typeRegistry);
        }

        @Override
        public void declareNameInScope(FlowScope scope, Node node, JSType type) {
            super.declareNameInScope(scope, node, type);
        }

        // Mocking getNativeType as it is used in the logic
        @Override
        protected JSType getNativeType(JSType type) {
            return mock(JSType.class);
        }
    }

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        interpreter = new TestableChainableReverseAbstractInterpreter(mockConvention, mockTypeRegistry);
    }

    @Test
    public void testDeclareNameInScope_TokenName() {
        // Arrange
        String name = "myVar";
        when(mockNode.getType()).thenReturn(Token.NAME);
        when(mockNode.getString()).thenReturn(name);

        // Act
        interpreter.declareNameInScope(mockScope, mockNode, mockType);

        // Assert
        verify(mockScope).inferSlotType(name, mockType);
    }

    @Test
    public void testDeclareNameInScope_TokenGetProp_WithOrigType() {
        // Arrange
        String qualifiedName = "obj.prop";
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn(qualifiedName);
        when(mockNode.getJSType()).thenReturn(mockOrigType);

        // Act
        interpreter.declareNameInScope(mockScope, mockNode, mockType);

        // Assert
        verify(mockScope).inferQualifiedSlot(mockNode, qualifiedName, mockOrigType, mockType);
    }

    @Test
    public void testDeclareNameInScope_TokenGetProp_WithNullOrigType() {
        // Arrange
        String qualifiedName = "obj.prop";
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn(qualifiedName);
        when(mockNode.getJSType()).thenReturn(null);

        // Act
        interpreter.declareNameInScope(mockScope, mockNode, mockType);

        // Assert
        // Verifies that getNativeType is called when origType is null
        verify(mockScope).inferQualifiedSlot(eq(mockNode), eq(qualifiedName), any(JSType.class), eq(mockType));
    }

    @Test
    public void testDeclareNameInScope_TokenGetProp_NullQualifiedNameThrows() {
        // Arrange
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn(null);

        // Act & Assert
        assertThrows(NullPointerException.class, () -> {
            interpreter.declareNameInScope(mockScope, mockNode, mockType);
        });
    }

    @Test
    public void testDeclareNameInScope_DefaultThrowsException() {
        // Arrange
        when(mockNode.getType()).thenReturn(Token.COMMA);
        when(mockNode.toStringTree()).thenReturn("testNode");

        // Act & Assert
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            interpreter.declareNameInScope(mockScope, mockNode, mockType);
        });

        Assert.assertTrue(exception.getMessage().contains("Node cannot be refined."));
        Assert.assertTrue(exception.getMessage().contains("testNode"));
    }
}
